     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Tetris</title>
     7	<style>
     8	  :root {
     9	    --cell: 28px;
    10	    --bg: #14161c;
    11	    --panel: #1e2129;
    12	    --line: #2a2e38;
    13	    --text: #e8eaf0;
    14	    --muted: #9aa0ad;
    15	  }
    16	  * { box-sizing: border-box; }
    17	  body {
    18	    margin: 0;
    19	    min-height: 100vh;
    20	    display: flex;
    21	    align-items: center;
    22	    justify-content: center;
    23	    background: var(--bg);
    24	    color: var(--text);
    25	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    26	  }
    27	  .game {
    28	    display: flex;
    29	    gap: 20px;
    30	    align-items: flex-start;
    31	    padding: 20px;
    32	  }
    33	  .board-wrap { position: relative; }
    34	  .board {
    35	    display: grid;
    36	    grid-template-columns: repeat(10, var(--cell));
    37	    grid-template-rows: repeat(20, var(--cell));
    38	    gap: 1px;
    39	    padding: 1px;
    40	    background: var(--line);
    41	    border: 2px solid var(--line);
    42	  }
    43	  .cell { background: var(--panel); }
    44	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
    45	  .cell[data-ghost="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.35); }
    46	  .overlay {
    47	    position: absolute;
    48	    inset: 0;
    49	    display: flex;
    50	    align-items: center;
    51	    justify-content: center;
    52	    background: rgba(0,0,0,0.6);
    53	    font-size: 24px;
    54	    font-weight: 600;
    55	  }
    56	  .side {
    57	    display: flex;
    58	    flex-direction: column;
    59	    gap: 14px;
    60	    min-width: 140px;
    61	  }
    62	  .box {
    63	    background: var(--panel);
    64	    border: 1px solid var(--line);
    65	    padding: 10px 12px;
    66	  }
    67	  .label {
    68	    font-size: 11px;
    69	    text-transform: uppercase;
    70	    letter-spacing: 0.08em;
    71	    color: var(--muted);
    72	  }
    73	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
    74	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
    75	  .mini {
    76	    display: grid;
    77	    grid-template-columns: repeat(4, 16px);
    78	    grid-template-rows: repeat(2, 16px);
    79	    gap: 1px;
    80	  }
    81	  .mini-cell { background: transparent; }
    82	  .hold { margin-top: 8px; min-height: 33px; }
    83	  button {
    84	    font: inherit;
    85	    color: var(--text);
    86	    background: var(--panel);
    87	    border: 1px solid var(--line);
    88	    padding: 8px 12px;
    89	    cursor: pointer;
    90	  }
    91	  button:hover { border-color: var(--muted); }
    92	  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
    93	  .p-I { background: #22c7e0; }
    94	  .p-O { background: #f2c511; }
    95	  .p-T { background: #9b4dca; }
    96	  .p-S { background: #3cb44b; }
    97	  .p-Z { background: #e6194b; }
    98	  .p-J { background: #2f6fdf; }
    99	  .p-L { background: #f58231; }
   100	</style>
   101	</head>
   102	<body>
   103	<div class="game">
   104	  <div class="board-wrap">
   105	    <div class="board" data-testid="board" id="board"></div>
   106	  </div>
   107	  <div class="side">
   108	    <div class="box">
   109	      <div class="label">Score</div>
   110	      <div class="value" data-testid="score" id="score">0</div>
   111	    </div>
   112	    <div class="box">
   113	      <div class="label">Level</div>
   114	      <div class="value" data-testid="level" id="level">1</div>
   115	    </div>
   116	    <div class="box">
   117	      <div class="label">Lines</div>
   118	      <div class="value" data-testid="lines" id="lines">0</div>
   119	    </div>
   120	    <div class="box">
   121	      <div class="label">Hold</div>
   122	      <div class="hold" data-testid="hold-piece" data-piece="" id="hold"></div>
   123	    </div>
   124	    <div class="box">
   125	      <div class="label">Next</div>
   126	      <div class="next-list" data-testid="next-piece" id="next"></div>
   127	    </div>
   128	    <button type="button" data-testid="pause-btn" id="pause">Pause</button>
   129	    <button type="button" id="new-game">New game</button>
   130	    <div class="help">
   131	      ← → move<br>
   132	      ↓ soft drop<br>
   133	      Space hard drop<br>
   134	      ↑ rotate<br>
   135	      C hold<br>
   136	      P pause
   137	    </div>
   138	  </div>
   139	</div>
   140	
   141	<script>
   142	(function () {
   143	  "use strict";
   144	
   145	  var ROWS = 20;
   146	  var COLS = 10;
   147	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
   148	  var PREVIEW = 1;
   149	  var LINES_PER_LEVEL = 10;
   150	  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
   151	  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move or soft drop restarts the delay
   152	
   153	  // Points for rows cleared at once, times the level. Clearing rows together
   154	  // must always beat clearing the same rows one at a time.
   155	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
   156	  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
   157	  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop
   158	
   159	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
   160	  var SHAPES = {
   161	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
   162	    O: { m: ["OO", "OO"], row: 0, col: 4 },
   163	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
   164	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
   165	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
   166	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
   167	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
   168	  };
   169	
   170	  // ---- State ----
   171	  var board;        // board[row][col] = "" or piece letter
   172	  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
   173	  var held;         // letter in the hold slot, or null
   174	  var holdUsed;     // true after a hold, until the next piece locks
   175	  var next;         // upcoming piece letters, soonest first
   176	  var scripted;     // true while `next` comes from a test-supplied queue
   177	  var bag = [];
   178	  var score, level, lines, status;
   179	  var timer = null;
   180	  var timerInterval = 0;
   181	  var stepDueAt = 0;      // Date.now() when the next gravity step fires
   182	  var pausedRemaining = 0; // ms left until the next gravity step, kept while paused
   183	
   184	  function emptyBoard() {
   185	    var b = [];
   186	    for (var r = 0; r < ROWS; r++) {
   187	      var row = [];
   188	      for (var c = 0; c < COLS; c++) row.push("");
   189	      b.push(row);
   190	    }
   191	    return b;
   192	  }
   193	
   194	  function randomType() {
   195	    if (bag.length === 0) {
   196	      bag = TYPES.slice();
   197	      for (var i = bag.length - 1; i > 0; i--) {
   198	        var j = Math.floor(Math.random() * (i + 1));
   199	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
   200	      }
   201	    }
   202	    return bag.pop();
   203	  }
   204	
   205	  function fillPreview() {
   206	    if (scripted) return;
   207	    while (next.length < PREVIEW) next.push(randomType());
   208	  }
   209	
   210	  function shapeCells(matrix, row, col) {
   211	    var cells = [];
   212	    for (var r = 0; r < matrix.length; r++) {
   213	      for (var c = 0; c < matrix[r].length; c++) {
   214	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
   215	      }
   216	    }
   217	    return cells;
   218	  }
   219	
   220	  function fits(matrix, row, col) {
   221	    var cells = shapeCells(matrix, row, col);
   222	    for (var i = 0; i < cells.length; i++) {
   223	      var r = cells[i][0], c = cells[i][1];
   224	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
   225	      if (board[r][c] !== "") return false;
   226	    }
   227	    return true;
   228	  }
   229	
   230	  // Milliseconds between gravity steps at the current level.
   231	  function dropInterval() {
   232	    return Math.max(100, 1000 - (level - 1) * 100);
   233	  }
   234	
   235	  function spawn() {
   236	    if (next.length === 0) scripted = false;
   237	    fillPreview();
   238	    var type = next.shift();
   239	    fillPreview();
   240	    enter(type);
   241	  }
   242	
   243	  // Puts a piece of the given type at the spawn position, or ends the game.
   244	  function enter(type) {
   245	    var s = SHAPES[type];
   246	    var piece = {
   247	      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
   248	      lockTicks: 0,   // consecutive gravity steps spent unable to fall
   249	      lockResets: 0   // lifetime count of lock-delay restarts
   250	    };
   251	    if (!fits(piece.matrix, piece.row, piece.col)) {
   252	      current = null;
   253	      status = "gameover";
   254	      stopTimer();
   255	      return;
   256	    }
   257	    current = piece;
   258	  }
   259	
   260	  function lock() {
   261	    var cells = shapeCells(current.matrix, current.row, current.col);
   262	    for (var i = 0; i < cells.length; i++) {
   263	      board[cells[i][0]][cells[i][1]] = current.type;
   264	    }
   265	    current = null;
   266	    holdUsed = false;
   267	    clearLines();
   268	    spawn();
   269	  }
   270	
   271	  // Sets the falling piece aside. The first hold brings in the next piece;
   272	  // later holds swap with the held one. Once per piece until it locks.
   273	  function hold() {
   274	    if (!current || holdUsed) return;
   275	    var type = current.type;
   276	    current = null;
   277	    holdUsed = true;
   278	    if (held === null) {
   279	      held = type;
   280	      spawn();
   281	    } else {
   282	      var out = held;
   283	      held = type;
   284	      enter(out);
   285	    }
   286	  }
   287	
   288	  // Removes every full row; rows above drop down.
   289	  function clearLines() {
   290	    var kept = board.filter(function (row) {
   291	      return row.some(function (v) { return v === ""; });
   292	    });
   293	    var cleared = ROWS - kept.length;
   294	    if (cleared === 0) return;
   295	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
   296	    board = kept;
   297	    // Points use the level the clear was made at.
   298	    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
   299	    var levelsGained = Math.floor((lines + cleared) / LINES_PER_LEVEL) -
   300	      Math.floor(lines / LINES_PER_LEVEL);
   301	    lines += cleared;
   302	    if (levelsGained > 0) setLevelValue(level + levelsGained);
   303	  }
   304	
   305	  // Changes the level and keeps the gravity timer in step with it.
   306	  function setLevelValue(n) {
   307	    level = n;
   308	    if (timer !== null && timerInterval !== dropInterval()) startTimer();
   309	  }
   310	
   311	  function tryMove(dr, dc) {
   312	    if (!current) return false;
   313	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
   314	    current.row += dr;
   315	    current.col += dc;
   316	    return true;
   317	  }
   318	
   319	  // The single gravity step, used by the real timer and tick().
   320	  // A step that cannot move the piece down counts one tick of lock delay.
   321	  // Returns true if the piece moved down.
   322	  function gravityStep() {
   323	    if (status !== "running" || !current) return false;
   324	    if (tryMove(1, 0)) {
   325	      current.lockTicks = 0;
   326	      return true;
   327	    }
   328	    current.lockTicks++;
   329	    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
   330	    return false;
   331	  }
   332	
   333	  // Restarts a running lock delay, up to MAX_LOCK_RESETS times per piece.
   334	  function restartLockDelay() {
   335	    if (current.lockTicks > 0 && current.lockResets < MAX_LOCK_RESETS) {
   336	      current.lockResets++;
   337	      current.lockTicks = 0;
   338	    }
   339	  }
   340	
   341	  // Soft drop. If the piece cannot fall, it counts like a sideways move:
   342	  // it restarts a running lock delay and never adds a lock tick itself.
   343	  function softDrop() {
   344	    if (tryMove(1, 0)) {
   345	      current.lockTicks = 0;
   346	      score += SOFT_DROP_POINTS;
   347	    } else {
   348	      restartLockDelay();
   349	    }
   350	  }
   351	
   352	  // Left/right. A move made while the lock delay is running restarts it.
   353	  function shift(dc) {
   354	    if (tryMove(0, dc)) restartLockDelay();
   355	  }
   356	
   357	  // Clockwise rotation. Tries the rotated shape in place, then shifted
   358	  // sideways; if none fit, the piece is left unchanged.
   359	  function rotateCW() {
   360	    if (!current) return;
   361	    var m = current.matrix;
   362	    var n = m.length;
   363	    var rotated = [];
   364	    for (var r = 0; r < n; r++) {
   365	      var line = "";
   366	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
   367	      rotated.push(line);
   368	    }
   369	    var kicks = [0, -1, 1, -2, 2];
   370	    for (var i = 0; i < kicks.length; i++) {
   371	      var nc = current.col + kicks[i];
   372	      if (fits(rotated, current.row, nc)) {
   373	        current.matrix = rotated;
   374	        current.col = nc;
   375	        return;
   376	      }
   377	    }
   378	  }
   379	
   380	  // Cells the falling piece would occupy if dropped straight down.
   381	  function ghostCells() {
   382	    if (!current) return [];
   383	    var row = current.row;
   384	    while (fits(current.matrix, row + 1, current.col)) row++;
   385	    return shapeCells(current.matrix, row, current.col);
   386	  }
   387	
   388	  // Pausing freezes the gravity timer part-way through its interval and
   389	  // resumes from the same point, so pause/resume cannot hold off a lock tick.
   390	  // Lock ticks and restarts belong to the piece and are left untouched.
   391	  function togglePause() {
   392	    if (status === "running") {
   393	      pausedRemaining = Math.max(0, stepDueAt - Date.now());
   394	      stopTimer();
   395	      status = "paused";
   396	    } else if (status === "paused") {
   397	      status = "running";
   398	      startTimer(pausedRemaining);
   399	    }
   400	  }
   401	
   402	  // Hard drop skips the lock delay.
   403	  function hardDrop() {
   404	    if (!current) return;
   405	    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
   406	    lock();
   407	  }
   408	
   409	  function applyInput(action) {
   410	    if (action === "pause") { togglePause(); return; }
   411	    if (status !== "running" || !current) return;
   412	    switch (action) {
   413	      case "left": shift(-1); break;
   414	      case "right": shift(1); break;
   415	      case "softDrop": softDrop(); break;
   416	      case "hardDrop": hardDrop(); break;
   417	      case "rotateCW":
   418	      case "rotate": rotateCW(); break;
   419	      case "hold": hold(); break;
   420	    }
   421	  }
   422	
   423	  // ---- Timer ----
   424	  function stopTimer() {
   425	    if (timer !== null) { clearTimeout(timer); timer = null; }
   426	  }
   427	
   428	  // Starts gravity at the current level. The first step comes after
   429	  // firstDelay ms (default: a full interval), later ones every interval.
   430	  function startTimer(firstDelay) {
   431	    stopTimer();
   432	    timerInterval = dropInterval();
   433	    scheduleStep(firstDelay === undefined ? timerInterval : Math.min(firstDelay, timerInterval));
   434	  }
   435	
   436	  function scheduleStep(delay) {
   437	    stepDueAt = Date.now() + delay;
   438	    timer = setTimeout(function () {
   439	      // Schedule first: a lock inside the step may restart or stop the timer.
   440	      scheduleStep(timerInterval);
   441	      gravityStep();
   442	      render();
   443	    }, delay);
   444	  }
   445	
   446	  // ---- Rendering (synchronous) ----
   447	  var boardEl = document.getElementById("board");
   448	  var nextEl = document.getElementById("next");
   449	  var holdEl = document.getElementById("hold");
   450	  var boardWrapEl = boardEl.parentNode;
   451	  var overlayEl = document.createElement("div");
   452	  overlayEl.className = "overlay";
   453	  overlayEl.setAttribute("data-testid", "game-over");
   454	  overlayEl.textContent = "Game over";
   455	  var pausedEl = document.createElement("div");
   456	  pausedEl.className = "overlay";
   457	  pausedEl.setAttribute("data-testid", "paused-indicator");
   458	  pausedEl.textContent = "Paused";
   459	  var pauseBtn = document.getElementById("pause");
   460	  var scoreEl = document.getElementById("score");
   461	  var levelEl = document.getElementById("level");
   462	  var linesEl = document.getElementById("lines");
   463	  var cellEls = [];
   464	
   465	  (function buildBoard() {
   466	    for (var r = 0; r < ROWS; r++) {
   467	      cellEls.push([]);
   468	      for (var c = 0; c < COLS; c++) {
   469	        var el = document.createElement("div");
   470	        el.className = "cell";
   471	        el.setAttribute("data-testid", "cell");
   472	        el.setAttribute("data-row", String(r));
   473	        el.setAttribute("data-col", String(c));
   474	        el.setAttribute("data-filled", "false");
   475	        el.setAttribute("data-piece", "");
   476	        el.setAttribute("data-ghost", "false");
   477	        boardEl.appendChild(el);
   478	        cellEls[r].push(el);
   479	      }
   480	    }
   481	  })();
   482	
   483	  // A ghost cell is drawn only where nothing else is; it is never filled.
   484	  function paintCell(el, piece, ghost) {
   485	    el.className = piece ? "cell p-" + piece : "cell";
   486	    el.setAttribute("data-filled", piece ? "true" : "false");
   487	    el.setAttribute("data-piece", piece);
   488	    el.setAttribute("data-ghost", ghost && !piece ? "true" : "false");
   489	  }
   490	
   491	  // Keeps an overlay in the DOM only while `show` is true.
   492	  function toggleOverlay(el, show) {
   493	    if (show) {
   494	      if (!el.parentNode) boardWrapEl.appendChild(el);
   495	    } else if (el.parentNode) {
   496	      el.parentNode.removeChild(el);
   497	    }
   498	  }
   499	
   500	  // A 4x2 picture of a piece in its spawn orientation.
   501	  function miniPiece(type) {
   502	    var m = SHAPES[type].m;
   503	    var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
   504	    var mini = document.createElement("div");
   505	    mini.className = "mini";
   506	    for (var r = 0; r < 2; r++) {
   507	      for (var c = 0; c < 4; c++) {
   508	        var ch = m[r + offset] && m[r + offset][c];
   509	        var cell = document.createElement("div");
   510	        cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
   511	        mini.appendChild(cell);
   512	      }
   513	    }
   514	    return mini;
   515	  }
   516	
   517	  function renderNext() {
   518	    nextEl.textContent = "";
   519	    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
   520	      var mini = miniPiece(next[i]);
   521	      mini.setAttribute("data-testid", "next-piece-item");
   522	      mini.setAttribute("data-piece", next[i]);
   523	      nextEl.appendChild(mini);
   524	    }
   525	  }
   526	
   527	  function renderHold() {
   528	    if (holdEl.getAttribute("data-piece") === (held || "")) return;
   529	    holdEl.textContent = "";
   530	    holdEl.setAttribute("data-piece", held || "");
   531	    if (held) holdEl.appendChild(miniPiece(held));
   532	  }
   533	
   534	  function render() {
   535	    var view = board.map(function (row) { return row.slice(); });
   536	    var ghost = board.map(function (row) { return row.map(function () { return false; }); });
   537	    var g = ghostCells();
   538	    for (var k = 0; k < g.length; k++) ghost[g[k][0]][g[k][1]] = true;
   539	    if (current) {
   540	      var cells = shapeCells(current.matrix, current.row, current.col);
   541	      for (var i = 0; i < cells.length; i++) {
   542	        view[cells[i][0]][cells[i][1]] = current.type;
   543	      }
   544	    }
   545	    for (var r = 0; r < ROWS; r++) {
   546	      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c], ghost[r][c]);
   547	    }
   548	    scoreEl.textContent = String(score);
   549	    levelEl.textContent = String(level);
   550	    linesEl.textContent = String(lines);
   551	    toggleOverlay(overlayEl, status === "gameover");
   552	    toggleOverlay(pausedEl, status === "paused");
   553	    pauseBtn.textContent = status === "paused" ? "Resume" : "Pause";
   554	    renderNext();
   555	    renderHold();
   556	  }
   557	
   558	  // ---- Game control ----
   559	  function validTypes(queue) {
   560	    if (!Array.isArray(queue)) return [];
   561	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
   562	  }
   563	
   564	  function newGame(queue) {
   565	    board = emptyBoard();
